draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // bell
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Bell', W/2 - 100, H/2);

  // food
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillText('Food', W/2 + 100, H/2);

  // dog
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 150, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 200);
  ctx.lineTo(W/2, H/2 + 250);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 25, H/2 + 200);
  ctx.lineTo(W/2 - 50, H/2 + 225);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 25, H/2 + 200);
  ctx.lineTo(W/2 + 50, H/2 + 225);
  ctx.stroke();

  // salivation
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 250);
  ctx.lineTo(W/2, H/2 + 300 + 50 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
